mapper.select:
SELECT locked_aftersale_no
FROM orders
WHERE order_no=#{orderNo}

mapper.update:
UPDATE orders
SET fulfillment_lock='NONE',locked_aftersale_no=NULL,version=version+1
WHERE order_no=#{orderNo} AND fulfillment_lock='AFTERSALE' AND locked_aftersale_no=#{sourceNo}

UPDATE refund_authorization
SET state=#{toState}
WHERE source_no=#{sourceNo} AND state=#{fromState}

UPDATE refund_authorization
SET state='SETTLING',settled_refund_no=#{settledRefundNo}
WHERE source_no=#{sourceNo} AND state='EXECUTING' AND settled_refund_no IS NULL

mapper.select:
SELECT settled_refund_no
FROM refund_authorization
WHERE source_no=#{sourceNo}

SELECT order_no,payment_no,status,total_amount_cents,currency,stock_sync_status,fulfillment_lock,pay_deadline,shipped_at,completed_at,created_at
FROM orders
WHERE merchant_id=#{merchantId}
ORDER BY id DESC
LIMIT #{size} OFFSET #{offset}

SELECT payload_hash
FROM order_refund_fact
WHERE event_id=#{eventId}

mapper.update:
UPDATE orders
SET status='CANCELLED',stock_sync_status='RESTOCKED',fulfillment_lock='NONE',locked_aftersale_no=NULL,closed_at=UTC_TIMESTAMP(3),version=version+1
WHERE order_no=#{orderNo} AND status='PAID' AND fulfillment_lock='AFTERSALE' AND locked_aftersale_no=#{sourceNo}

UPDATE refund_flow_task
SET state='RUNNING',claim_version=claim_version+1,attempt_count=attempt_count+1,lease_owner=#{leaseOwner},lease_until=UTC_TIMESTAMP(3)+INTERVAL 30 SECOND
WHERE source_no=#{sourceNo}

UPDATE refund_flow_task
SET state=#{state},step=#{step},lease_until=NULL,last_error=#{lastError},next_retry_at=UTC_TIMESTAMP(3)+INTERVAL 5 SECOND
WHERE source_no=#{sourceNo} AND state='RUNNING' AND claim_version=#{claimVersion}
